package io.github.sifensdk.core.signing;

import java.util.Arrays;
import java.util.Objects;

/**
 * The taxpayer's security code for the QR (CSC, código de seguridad del contribuyente) and its
 * identifier ({@code IdCSC}).
 *
 * <p>Manual Técnico v150, 13.8.1: the secret has 32 alphanumeric characters, is generated by SIFEN
 * and handed to the taxpayer when it becomes an electronic invoicer; up to two codes can be active.
 * It is only used to compute the QR hash ({@code cHashQR}) and never travels in the QR or the XML
 * (13.8.4.2).
 *
 * <p>The Manual publishes two test codes, {@code 0001} = {@code ABCD} followed by 28 zeros and
 * {@code 0002} = {@code EFGH} followed by 28 zeros. They are for the test environment only and must
 * never be used in production: signing for {@link io.github.sifensdk.core.Environment#PRODUCTION}
 * with one of them is rejected (see {@link #isPublishedTestCode()}).
 *
 * <p>Immutable and thread-safe. The secret is copied on creation and on every read, so the caller
 * can clear its own array; {@link #toString()} shows only the identifier.
 */
public final class Csc {

  private static final String TEST_SECRET_1 = "ABCD0000000000000000000000000000";
  private static final String TEST_SECRET_2 = "EFGH0000000000000000000000000000";

  private final String id;
  private final char[] secret;

  private Csc(String id, char[] secret) {
    this.id = id;
    this.secret = secret;
  }

  /**
   * Creates a CSC.
   *
   * @param id the identifier of the code ({@code IdCSC}), 4 digits, for example {@code 0001}
   * @param secret the 32 alphanumeric characters given by SIFEN; the array is copied, not kept
   * @return the CSC
   * @throws IllegalArgumentException if the identifier is not 4 digits or the secret is not 32
   *     alphanumeric characters (the message never contains the secret)
   */
  public static Csc of(String id, char[] secret) {
    Objects.requireNonNull(id, "id");
    Objects.requireNonNull(secret, "secret");
    if (id.length() != 4 || !id.chars().allMatch(c -> c >= '0' && c <= '9')) {
      throw new IllegalArgumentException("The CSC identifier (IdCSC) must have 4 digits");
    }
    if (secret.length != 32) {
      throw new IllegalArgumentException(
          "The CSC must have 32 characters (Manual Técnico v150, 13.8.1)");
    }
    for (char c : secret) {
      boolean alphanumeric =
          (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
      if (!alphanumeric) {
        throw new IllegalArgumentException(
            "The CSC must have only alphanumeric characters (Manual Técnico v150, 13.8.1)");
      }
    }
    return new Csc(id, secret.clone());
  }

  /**
   * Returns the identifier of the code ({@code IdCSC}).
   *
   * @return 4 digits
   */
  public String id() {
    return id;
  }

  /**
   * Returns a copy of the secret. The caller should clear the array when done with it.
   *
   * @return a new array with the 32 characters of the secret
   */
  public char[] secret() {
    return secret.clone();
  }

  /**
   * Tells whether this is one of the test codes published in the Manual Técnico ({@code 0001} =
   * {@code ABCD} + 28 zeros, {@code 0002} = {@code EFGH} + 28 zeros), which must not be used in
   * production.
   *
   * @return {@code true} if the secret is one of the published test secrets
   */
  public boolean isPublishedTestCode() {
    return Arrays.equals(secret, TEST_SECRET_1.toCharArray())
        || Arrays.equals(secret, TEST_SECRET_2.toCharArray());
  }

  /** Returns the identifier only; never the secret. */
  @Override
  public String toString() {
    return "Csc[id=" + id + "]";
  }
}
